def _init_schema(self):
    # PATCH v1.0.6: понятная ошибка, если schema.sql отсутствует
    if not SCHEMA_PATH.exists():
        raise RuntimeError(
            f'Файл схемы не найден: {SCHEMA_PATH}. Положите schema.sql рядом с db.py.'
        )
    try:
        sql = SCHEMA_PATH.read_text(encoding='utf-8')
    except Exception as e:
        raise RuntimeError(f'Не удалось прочитать схему {SCHEMA_PATH}: {e}')
    c = self._make_conn()
    try:
        c.executescript(sql)
        # PATCH revert_kody: kody_hash → password_hash
        try:
            cols = [r[1] for r in c.execute('PRAGMA table_info(users)').fetchall()]
            if 'kody_hash' in cols and 'password_hash' not in cols:
                c.execute('ALTER TABLE users RENAME COLUMN kody_hash TO password_hash')
                print('[db] migrated users.kody_hash → password_hash')
            elif 'kody_hash' in cols and 'password_hash' in cols:
                c.execute(
                    'UPDATE users SET password_hash = kody_hash '
                    "WHERE (password_hash IS NULL OR password_hash = '') "
                    "AND kody_hash IS NOT NULL AND kody_hash != ''"
                )
        except Exception as _me:
            print(f'[db] kody→password migration skipped: {_me}')
    finally:
        c.close()

@app.route('/api/settings/password', methods=['POST'])
    @app.route('/api/settings/kody', methods=['POST'])
    @login_required
    def api_change_password():
        u = current_user(db)
        body = request.get_json() or {}
        old = body.get('old_password') or body.get('old_kody') or ''
        new = body.get('new_password') or body.get('new_kody') or ''
        if len(new) < 6:
            return jsonify({'success': False, 'error': 'пароль минимум 6 символов'}), 400
        _hash = (u or {}).get('password_hash') or (u or {}).get('kody_hash') or ''
        if not _hash or not verify_kody(_hash, old):
            return jsonify({'success': False, 'error': 'Неверный текущий пароль'}), 400
        db.user_update(
            u['id'], u['role'], u.get('display_name', ''),
            u.get('employee_id', ''), True, pwd_hash=hash_kody(new)
        )
        _audit(db, u, 'update', 'user', u['id'], {'password_changed': True})
        return jsonify({'success': True})

